    async def measure(self,tag):
        await self.page.evaluate('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))')
        r=await self.page.evaluate('''()=>{const visible=n=>n.getClientRects().length&&getComputedStyle(n).visibility==='visible';const controls=[...document.querySelectorAll('[data-journey-previous],.journey-return-link,.journey-step-footer>button:not([hidden]),.journey-sequential-footer>button')].filter(visible);return {width:innerWidth,scroll:document.documentElement.scrollWidth,client:document.documentElement.clientWidth,controls:controls.map(n=>({label:n.textContent,rect:n.getBoundingClientRect().toJSON(),container:n.closest('.core-wizard-workspace,.journey-studio-content,.d-page-header')?.getBoundingClientRect().toJSON()})),heading:document.querySelector('.ultimate-core-setup h1')?.getBoundingClientRect().toJSON(),origin:document.querySelector('.journey-return-link')?.getBoundingClientRect().toJSON()}}''')
        self.assertLessEqual(r['scroll'],r['client'],r)
        for item in r['controls']:
            self.assertGreaterEqual(item['rect']['left'],-1,r);self.assertLessEqual(item['rect']['right'],r['client']+1,r)
            if item['container']:self.assertGreaterEqual(item['rect']['left'],item['container']['left']-1,r);self.assertLessEqual(item['rect']['right'],item['container']['right']+1,r)
        for i,a in enumerate(r['controls']):
            for b in r['controls'][i+1:]:
                x,y=a['rect'],b['rect'];overlap=x['left']<y['right']-1 and x['right']>y['left']+1 and x['top']<y['bottom']-1 and x['bottom']>y['top']+1;self.assertFalse(overlap,r)
        if r['heading'] and r['origin']:
            a,b=r['heading'],r['origin'];self.assertFalse(a['left']<b['right']-1 and a['right']>b['left']+1 and a['top']<b['bottom']-1 and a['bottom']>b['top']+1,r)
        await expect(self.page.locator('#journey-nav [aria-current=step][href]')).to_have_count(0)
        await expect(self.page.locator('#dda-workspace-nav-shell')).to_be_hidden();await expect(self.page.locator('#journey-nav li')).to_have_count(4)
        r['scenario']=tag;MEASUREMENTS.append(r);(OUT/'geometry.json').write_text(json.dumps(MEASUREMENTS,indent=2))
        audit=await self.page.evaluate((Path(__file__).parent/'theme_audit.js').read_text());self.assertEqual(audit['failures'],[],audit['failures']);CONTRAST.append({'width':r['width'],'scenario':tag,'textCount':audit['textCount'],'minimumContrast':audit['minimumContrast'],'failures':audit['failures']});(OUT/'contrast.json').write_text(json.dumps(CONTRAST,indent=2))
