    async def test_09_late_context_return_is_canceled_by_local_previous(self):
        _,_,c=await self.case();cid=c['case']['id'];await self.full(cid);await self.page.goto(self.base+'/app/ddas/logistics/configure?case_id='+cid+'&node_id=logistics_assignment',wait_until='domcontentloaded');await self.page.locator('[data-graph-config]').wait_for();await self.page.locator('#journey-nav').get_by_role('link',name='Core Configuration',exact=True).click();await self.ready(3);await expect(self.page.locator('.journey-return-link')).to_contain_text('Decision Configuration');entered=asyncio.Event();release=asyncio.Event();finished=asyncio.Event();self.addCleanup(release.set)
